blocks.code:
terraform {
  required_providers {
    iosxe = {
      source = "CiscoDevNet/iosxe"
    }
  }
}

provider "iosxe" {
  url      = "https://192.0.2.21"     # device reached over RESTCONF
  username = "automation"
  password = var.iosxe_password        # supplied at run time, never hard-coded
}

resource "iosxe_vlan" "voice" {
  vlan_id = 30
  name    = "VOICE"
}

lines.output:
native {
    device {
        name sw1
        data vlan 30
              name VOICE
             !
    }
}

